        ease: [...motionTokens.easing[RELAYOUT.move]],
        enterAt: RELAYOUT.enterAt,
        enterMs: motionTokens.duration[RELAYOUT.enter] * timeScale,
        enterEase: LINEAR,
        exitMs: motionTokens.duration[RELAYOUT.exit] * timeScale,
